for bundle in b['bundles']:
 if bundle['id']=='web-research':
  bundle['skills'] += ['browser-session-isolation','structured-web-extraction','bounded-crawl-planning'];bundle['version']='0.2.0'
 if bundle['id']=='mcp-tooling':bundle['skills']+=['mcp-server-qualification'];bundle['version']='0.2.0'
(R/'catalog/bundles.json').write_text(json.dumps(b,indent=2)+'\n')
